namespace Algorithms.Backtracking;
public static partial class Backtracking
{
    public static int[][]? SolveSudoku(int[][] input) { var board = input.Select(r => r.ToArray()).ToArray(); var rows = Enumerable.Range(0, 9).Select(_ => new HashSet<int>()).ToArray(); var cols = Enumerable.Range(0, 9).Select(_ => new HashSet<int>()).ToArray(); var boxes = Enumerable.Range(0, 9).Select(_ => new HashSet<int>()).ToArray(); var empty = new List<(int, int)>(); int Box(int r, int c) => r / 3 * 3 + c / 3; for (var r = 0; r < 9; r++) for (var c = 0; c < 9; c++) { var v = board[r][c]; if (v == 0) { empty.Add((r, c)); continue; } if (rows[r].Contains(v) || cols[c].Contains(v) || boxes[Box(r, c)].Contains(v)) return null; rows[r].Add(v); cols[c].Add(v); boxes[Box(r, c)].Add(v); } bool Fill(int index) { if (index == empty.Count) return true; var (r, c) = empty[index]; var b = Box(r, c); for (var v = 1; v <= 9; v++) { if (rows[r].Contains(v) || cols[c].Contains(v) || boxes[b].Contains(v)) continue; board[r][c] = v; rows[r].Add(v); cols[c].Add(v); boxes[b].Add(v); if (Fill(index + 1)) return true; board[r][c] = 0; rows[r].Remove(v); cols[c].Remove(v); boxes[b].Remove(v); } return false; } return Fill(0) ? board : null; }
}
